/* Signature Lao Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Khampha": "From kham (gold) + pha (bring): 'bringer of gold'.", "Bounsavanh": "From boun (merit) + savanh (heaven): 'merit of heaven'.", "Malaykham": "From malay (jasmine) + kham (gold): 'golden jasmine'.", "Chanhvilay": "From chanh (moon) + vilay (turn/era): 'moon era'.", "Souvanhna": "From souvanh (gold) + na (field): 'golden field'.", "Phetmany": "From phet (diamond) + many (jewel): 'diamond jewel'.", "Khamvilay": "From kham (gold) + vilay: Signature surname, 'golden turn'.", "Bounpaseuth": "From boun (merit) + paseuth (noble): Signature surname.", "Savanhkham": "From savanh (heaven) + kham (gold): Signature surname.", "Malaythong": "From malay (jasmine) + thong (gold): Signature surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Khampha';
console.log(lookup(q));

